      sentence = "After all, you said yes to my proposal. Everything is only just beginning.",
      voice = 2,
      next = {242}
    },
    [242] = {
      beijing = 0,
      dhead = 107,
      dialog = 1,
      music = "18_Sorrow_love",
      renming = "$u",
      renwu = "npc",
      sentence = "I want lots of sunflowers, because I read in a book once that in the northern territories, there's a flower as brilliant as the sun.",
      next = {243}
    },
    [243] = {
      beijing = 0,
      dhead = 107,
      dialog = 1,
      music = "18_Sorrow_love",
      renming = "$u",
      renwu = "npc",
      sentence = "And it loves to open its blossom toward the sun... But it's okay if we can't get those. All I need is you.",
      next = {244}
    },
    [244] = {
      beijing = 0,
      dialog = 2,
      idx = 3,
      male = 3,
      music = "18_Sorrow_love",
      renming = "Kiro",
      renwu = "npc",
      sentence = "Now, that won't do. And don't stop at sunflowers.",
      voice = 2,
      next = {245}
    },
    [245] = {
      beijing = 0,
      dialog = 2,
      idx = 3,
      male = 3,
      music = "18_Sorrow_love",
      renming = "Kiro",
      renwu = "npc",
      sentence = "Whatever you want, I can get it for you.",
      voice = 2,
      next = {246}
    },
    [246] = {
      beijing = 0,
      dhead = 107,
      dialog = 1,
      music = "18_Sorrow_love",
      renming = "$u",
      renwu = "npc",
      sentence = "Then...",
      next = {247}
    },
    [247] = {
      beijing = 0,
      dialog = 3,
      music = "18_Sorrow_love",
      renwu = "npc",
      sentence = "My consciousness was starting to blur, but the heart next to my ear was still beating loud and clear.",
      sfx = "Heart_Beat",
      next = {248}
    },
    [248] = {
      beijing = 0,
      dialog = 3,
      music = "18_Sorrow_love",
      renwu = "npc",
      sentence = "It made me feel safe.",
      next = {249}
    },
    [249] = {
      beijing = 0,
      dialog = 3,
      music = "18_Sorrow_love",
      renwu = "npc",
      sentence = "So safe that I wanted this moment to stretch on for eternity.",
      next = {250}
    },
    [250] = {
      beijing = 4839,
      bganim = 0,
      dialog = 3,
      music = "61_Feeling_Blue",
      renwu = "npc",
      sentence = "The girl stopped responding, and she wasn't breathing either. There was nothing from her body but some lingering warmth under the advancing flames.",
      next = {251}
    },
    [251] = {
      beijing = 4839,
      dialog = 3,
      music = "61_Feeling_Blue",
      renwu = "npc",
      sentence = "As if not wanting to let this warmth slip from his arms, Kiro used the last of his strength holding the girl tight and kissing her forehead.",
      next = {252}
    },
    [252] = {
      beijing = 53791,
      bganim = 0,
      card_cg_anim = "CG_431094_252",
      dialog = 2,
      idx = 3,
      male = 3,
      music = "61_Feeling_Blue",
      renming = "Kiro",
      renwu = "npc",
      sentence = "I know you're afraid I'd be lonely buried here facing endless darkness by myself.",
      voice = 2,
      next = {253}
    },
    [253] = {
      beijing = 53791,
      card_cg_anim = "none",
      dialog = 2,
      idx = 3,
      male = 3,
      music = "61_Feeling_Blue",
      renming = "Kiro",
      renwu = "npc",
      sentence = "But I was hoping you'd still be able to see the sunshine every day and smell the flowers in my place...",
      voice = 2,
      next = {254}
    },
    [254] = {
      beijing = 53791,
      card_cg_anim = "none",
      dialog = 2,
      idx = 3,
      male = 3,
      music = "61_Feeling_Blue",
      renming = "Kiro",
      renwu = "npc",
      sentence = "Although this isn't too bad either.",
      voice = 2,
      next = {255}
    },
    [255] = {
      beijing = 53791,
      card_cg_anim = "none",
      dialog = 2,
      idx = 3,
      male = 3,
      music = "61_Feeling_Blue",
      renming = "Kiro",
      renwu = "npc",
      sentence = "But I can never repay you what I owe.",
      voice = 2,
      next = {256}
    },
    [256] = {
      beijing = 53791,
      card_cg_anim = "CG_431094_256",
      dialog = 3,
      music = "61_Feeling_Blue",
      renwu = "npc",
      sentence = "Kiro paused, and a moment later, he laid one last kiss on her forehead, cherishing and tender, and then let out a flat laugh.",
      next = {257}
    },
    [257] = {
      beijing = 53791,
      card_cg_anim = "none",
      dialog = 2,
      idx = 3,
      male = 3,
      music = "61_Feeling_Blue",
      renming = "Kiro",
      renwu = "npc",
      sentence = "I have no expectations. Just that I might see you in the next life.",
      voice = 2,
      next = {258}
    },
    [258] = {
      beijing = 53791,
      card_cg_anim = "none",
      dialog = 2,
      idx = 3,
      male = 3,
      music = "61_Feeling_Blue",
      renming = "Kiro",
      renwu = "npc",
      sentence = "If I come back as an animal, I'll stand guard at your feet day and night.",
      voice = 2,
      next = {259}
    },
    [259] = {
      beijing = 53791,
      card_cg_anim = "CG_431094_259",
      dialog = 2,
      idx = 3,
      male = 3,
      music = "61_Feeling_Blue",
      renming = "Kiro",
      renwu = "npc",
      sentence = "If I'm a flower, then I'll only blossom for you.",
      voice = 2,
      next = {260}
    },
    [260] = {
      beijing = 53791,
      card_cg_anim = "none",
      dialog = 2,
      idx = 3,
      male = 3,
      music = "61_Feeling_Blue",
      renming = "Kiro",
      renwu = "npc",
      sentence = "And if I'm unlucky enough to come back as a rock, then I'll roll down off the mountain to find you.",
      voice = 2,
      next = {261}
    },
    [261] = {
      beijing = 53791,
      card_cg_anim = "none",
      dialog = 2,
      idx = 3,
      male = 3,
      music = "61_Feeling_Blue",
      renming = "Kiro",
      renwu = "npc",
      sentence = "Of course, coming back as a person would be best.",
      voice = 2,
      next = {262}
    },
    [262] = {
      beijing = 53791,
      card_cg_anim = "none",
      dialog = 2,
      idx = 3,
      male = 3,
      music = "61_Feeling_Blue",
      renming = "Kiro",
      renwu = "npc",
      sentence = "That way, I could hold you, kiss you, and love you forever and ever.",
      voice = 2,
      next = {263}
    },
    [263] = {
      beijing = 53791,
      card_cg_anim = "CG_431094_263_2",
      dialog = 3,
      music = "61_Feeling_Blue",
      renwu = "npc",
      sentence = "Kiro's voice grew weaker until it finally turned into a sigh fading in the wind.",
      next = {264}
    },
    [264] = {
      beijing = 53791,
      card_cg_anim = "none",
      dialog = 2,
      idx = 3,
      male = 3,
      music = "61_Feeling_Blue",
      renming = "Kiro",
      renwu = "npc",
      sentence = "I promise you.",
      voice = 2,
      next = {265}
    },
    [265] = {
      beijing = 1,
      bganim = 1,
      card_cg_anim = "none",
      dialog = 3,
      music = "61_Feeling_Blue",
      renwu = "npc",
      sentence = "Kiro closed his eyes peacefully, but he could see a light as dazzling as the sun about to envelop him.",
      next = {266}
    },
    [266] = {
      beijing = 1,
      dialog = 3,
      music = "61_Feeling_Blue",
      renwu = "npc",
      sentence = "What it was, he didn't know.",
